import { exactHandVsHand } from './exact'
import { monteCarloHandVsRange } from './montecarlo'

export type WorkerRequest =
  | {
      id: number
      type: 'exact'
      hero: [number, number]
      villain: [number, number]
    }
  | {
      id: number
      type: 'montecarlo'
      hero: [number, number]
      combos: number[][]
      iterations: number
    }

export type WorkerResponse =
  | {
      id: number
      type: 'progress'
      done: number
      total: number
    }
  | {
      id: number
      type: 'result'
      result: ReturnType<typeof exactHandVsHand> | ReturnType<typeof monteCarloHandVsRange>
    }
  | {
      id: number
      type: 'error'
      message: string
    }

self.onmessage = (ev: MessageEvent<WorkerRequest>) => {
  const msg = ev.data
  try {
    if (msg.type === 'exact') {
      const result = exactHandVsHand(msg.hero, msg.villain, (done, total) => {
        const res: WorkerResponse = { id: msg.id, type: 'progress', done, total }
        self.postMessage(res)
      })
      const res: WorkerResponse = { id: msg.id, type: 'result', result }
      self.postMessage(res)
      return
    }

    if (msg.type === 'montecarlo') {
      const result = monteCarloHandVsRange(msg.hero, msg.combos, msg.iterations, (done, total) => {
        const res: WorkerResponse = { id: msg.id, type: 'progress', done, total }
        self.postMessage(res)
      })
      const res: WorkerResponse = { id: msg.id, type: 'result', result }
      self.postMessage(res)
    }
  } catch (e) {
    const res: WorkerResponse = {
      id: msg.id,
      type: 'error',
      message: e instanceof Error ? e.message : String(e),
    }
    self.postMessage(res)
  }
}
