/**
 * Évaluateur 7 cartes NLH — score entier comparable (plus haut = mieux).
 * Catégories : 8 SF … 0 high card. Kickers encodés pour départager.
 */

const RANK_MASKS = new Uint16Array(13)
for (let i = 0; i < 13; i++) RANK_MASKS[i] = 1 << i

/** Bitmask A-high straight patterns (bits 0=2 … 12=A). Wheel = A2345. */
const STRAIGHT_MASKS: { mask: number; high: number }[] = [
  { mask: 0b1111100000000, high: 12 }, // AKQJT
  { mask: 0b0111110000000, high: 11 },
  { mask: 0b0011111000000, high: 10 },
  { mask: 0b0001111100000, high: 9 },
  { mask: 0b0000111110000, high: 8 },
  { mask: 0b0000011111000, high: 7 },
  { mask: 0b0000001111100, high: 6 },
  { mask: 0b0000000111110, high: 5 },
  { mask: 0b0000000011111, high: 4 }, // 65432
  { mask: 0b1000000001111, high: 3 }, // A5432
]

function straightHigh(rankBits: number): number {
  for (let i = 0; i < STRAIGHT_MASKS.length; i++) {
    const s = STRAIGHT_MASKS[i]!
    if ((rankBits & s.mask) === s.mask) return s.high
  }
  return -1
}

function topKickers(rankCounts: Int8Array, n: number, exclude1 = -1, exclude2 = -1): number {
  let score = 0
  let found = 0
  for (let r = 12; r >= 0 && found < n; r--) {
    if (r === exclude1 || r === exclude2) continue
    const c = rankCounts[r]!
    for (let k = 0; k < c && found < n; k++) {
      score = (score << 4) | r
      found++
    }
  }
  while (found < n) {
    score <<= 4
    found++
  }
  return score
}

/**
 * Évalue 7 cartes (ids 0–51). Retourne un score 32-bit.
 * Layout : cat(4) | d1(4) | d2(4) | k1(4) | k2(4) | k3(4) | k4(4) | k5(4) — cat en bits hauts.
 */
export function evaluate7(
  c0: number,
  c1: number,
  c2: number,
  c3: number,
  c4: number,
  c5: number,
  c6: number,
): number {
  const rankCounts = new Int8Array(13)
  const suitCounts = new Int8Array(4)
  const suitRankBits = [0, 0, 0, 0]

  const cards = [c0, c1, c2, c3, c4, c5, c6]
  let allRankBits = 0

  for (let i = 0; i < 7; i++) {
    const id = cards[i]!
    const r = id % 13
    const s = (id / 13) | 0
    rankCounts[r]++
    suitCounts[s]++
    suitRankBits[s]! |= RANK_MASKS[r]!
    allRankBits |= RANK_MASKS[r]!
  }

  // Flush / straight flush
  let flushSuit = -1
  for (let s = 0; s < 4; s++) {
    if (suitCounts[s]! >= 5) {
      flushSuit = s
      break
    }
  }

  if (flushSuit >= 0) {
    const fb = suitRankBits[flushSuit]!
    const sfHigh = straightHigh(fb)
    if (sfHigh >= 0) {
      return (8 << 24) | (sfHigh << 20)
    }
    // Flush : 5 plus hautes du suit
    let flushScore = 5 << 24
    let n = 0
    for (let r = 12; r >= 0 && n < 5; r--) {
      if (fb & RANK_MASKS[r]!) {
        flushScore |= r << (16 - n * 4)
        n++
      }
    }
    return flushScore
  }

  const stHigh = straightHigh(allRankBits)
  // Quads / full house / trips / pairs
  let quad = -1
  let trip1 = -1
  let trip2 = -1
  let pair1 = -1
  let pair2 = -1

  for (let r = 12; r >= 0; r--) {
    const c = rankCounts[r]!
    if (c === 4) quad = r
    else if (c === 3) {
      if (trip1 < 0) trip1 = r
      else trip2 = r
    } else if (c === 2) {
      if (pair1 < 0) pair1 = r
      else if (pair2 < 0) pair2 = r
      // 3e paire possible en 7 cartes : ignorée (on garde les 2 meilleures)
    }
  }

  if (quad >= 0) {
    const kicker = topKickers(rankCounts, 1, quad)
    return (7 << 24) | (quad << 20) | (kicker << 16)
  }

  // Full house : trips + pair, ou deux trips, ou trips + meilleure pair
  if (trip1 >= 0 && (pair1 >= 0 || trip2 >= 0)) {
    const pairRank = trip2 >= 0 ? trip2 : pair1
    return (6 << 24) | (trip1 << 20) | (pairRank << 16)
  }

  if (stHigh >= 0) {
    return (4 << 24) | (stHigh << 20)
  }

  if (trip1 >= 0) {
    const kickers = topKickers(rankCounts, 2, trip1)
    return (3 << 24) | (trip1 << 20) | kickers
  }

  if (pair1 >= 0 && pair2 >= 0) {
    const kicker = topKickers(rankCounts, 1, pair1, pair2)
    return (2 << 24) | (pair1 << 20) | (pair2 << 16) | (kicker << 12)
  }

  if (pair1 >= 0) {
    const kickers = topKickers(rankCounts, 3, pair1)
    return (1 << 24) | (pair1 << 20) | kickers
  }

  const kickers = topKickers(rankCounts, 5)
  return (0 << 24) | kickers
}

export function evaluate7Arr(cards: number[]): number {
  return evaluate7(cards[0]!, cards[1]!, cards[2]!, cards[3]!, cards[4]!, cards[5]!, cards[6]!)
}
