import { evaluate7 } from './evaluator'

export interface EquityResult {
  equity: number
  win: number
  tie: number
  lose: number
  boards: number
  elapsedMs: number
  method: 'exact' | 'montecarlo'
}

/**
 * Équité exacte préflop hand vs hand : énumère C(48,5) boards.
 * equity = (wins + ties/2) / boards  (définition Equilab).
 */
export function exactHandVsHand(
  h1: [number, number],
  h2: [number, number],
  onProgress?: (done: number, total: number) => void,
): EquityResult {
  const used = new Uint8Array(52)
  used[h1[0]] = 1
  used[h1[1]] = 1
  used[h2[0]] = 1
  used[h2[1]] = 1

  const deck: number[] = []
  for (let i = 0; i < 52; i++) if (!used[i]) deck.push(i)
  const n = deck.length // 48
  const total = (n * (n - 1) * (n - 2) * (n - 3) * (n - 4)) / 120 // C(48,5)

  let wins = 0
  let ties = 0
  let lose = 0
  let counted = 0
  const t0 = performance.now()
  const progressEvery = 150_000

  const a0 = h1[0]
  const a1 = h1[1]
  const b0 = h2[0]
  const b1 = h2[1]

  for (let i = 0; i < n - 4; i++) {
    const c0 = deck[i]!
    for (let j = i + 1; j < n - 3; j++) {
      const c1 = deck[j]!
      for (let k = j + 1; k < n - 2; k++) {
        const c2 = deck[k]!
        for (let l = k + 1; l < n - 1; l++) {
          const c3 = deck[l]!
          for (let m = l + 1; m < n; m++) {
            const c4 = deck[m]!
            const s1 = evaluate7(a0, a1, c0, c1, c2, c3, c4)
            const s2 = evaluate7(b0, b1, c0, c1, c2, c3, c4)
            if (s1 > s2) wins++
            else if (s1 < s2) lose++
            else ties++
            counted++
            if (onProgress && counted % progressEvery === 0) {
              onProgress(counted, total)
            }
          }
        }
      }
    }
  }

  const equity = ((wins + ties * 0.5) / counted) * 100
  return {
    equity,
    win: wins,
    tie: ties,
    lose,
    boards: counted,
    elapsedMs: performance.now() - t0,
    method: 'exact',
  }
}
