import { evaluate7 } from './evaluator'

export interface MonteCarloResult {
  equity: number
  win: number
  tie: number
  lose: number
  iterations: number
  elapsedMs: number
  method: 'montecarlo'
  stdError: number
}

/** Fisher–Yates partiel : tire `count` cartes distinctes depuis deck (muté en place via swap). */
function sampleBoard(
  deck: number[],
  n: number,
  out: number[],
): void {
  // Tirage sans remise des 5 premières positions
  for (let i = 0; i < 5; i++) {
    const j = i + ((Math.random() * (n - i)) | 0)
    const tmp = deck[i]!
    deck[i] = deck[j]!
    deck[j] = tmp
    out[i] = deck[i]!
  }
}

/**
 * Monte Carlo hand vs range (préflop).
 * Chaque itération : combo uniforme dans la range (card removal déjà appliqué),
 * board aléatoire parmi les 48−2 cartes restantes.
 */
export function monteCarloHandVsRange(
  hero: [number, number],
  combos: number[][],
  iterations: number,
  onProgress?: (done: number, total: number) => void,
): MonteCarloResult {
  if (combos.length === 0) {
    throw new Error('Range vide (aucun combo possible après card removal)')
  }

  const t0 = performance.now()
  let wins = 0
  let ties = 0
  let lose = 0

  const hero0 = hero[0]
  const hero1 = hero[1]
  const board = new Array<number>(5)
  const progressEvery = Math.max(5_000, (iterations / 20) | 0)

  for (let it = 0; it < iterations; it++) {
    const combo = combos[(Math.random() * combos.length) | 0]!
    const v0 = combo[0]!
    const v1 = combo[1]!

    const deck: number[] = []
    for (let c = 0; c < 52; c++) {
      if (c !== hero0 && c !== hero1 && c !== v0 && c !== v1) deck.push(c)
    }
    const n = deck.length
    sampleBoard(deck, n, board)

    const s1 = evaluate7(hero0, hero1, board[0]!, board[1]!, board[2]!, board[3]!, board[4]!)
    const s2 = evaluate7(v0, v1, board[0]!, board[1]!, board[2]!, board[3]!, board[4]!)
    if (s1 > s2) wins++
    else if (s1 < s2) lose++
    else ties++

    if (onProgress && (it + 1) % progressEvery === 0) {
      onProgress(it + 1, iterations)
    }
  }

  const equity = ((wins + ties * 0.5) / iterations) * 100
  // Erreur std approx. binomiale pour proportion
  const p = equity / 100
  const stdError = Math.sqrt((p * (1 - p)) / iterations) * 100

  return {
    equity,
    win: wins,
    tie: ties,
    lose,
    iterations,
    elapsedMs: performance.now() - t0,
    method: 'montecarlo',
    stdError,
  }
}
